// folded-card.js — A REFERENT'S FOLDED IDENTITY, AS PLAIN INFORMATION (2026-10-27; eval/referents/PREREG-FOLDED-CARD.md, reading-rules-audit/THE-FOLDED-CARD.md).
//
// The user: "If we don't want it to be answering what the model thinks about Natasha, we want it to be given the holographic identity of Natasha and be asking questions about her." A referent is not a
// spelling; it is the fold at a point, for a for-whom (identity-at-a-point). This renders that fold, from the referent ledger (reading-referents.js, `entry.referents`), as a card a model can read:
// plain prose, the question kept apart as the last turn (Archon Gary's rules: no-address, no-apparatus, no-json-ask, information-not-prohibition, question-last, fits-the-window).
//
//   renderCard(entry, referentId, { asOf, forWhom, question, window, stated, declension, swap })
//     → { text, question, messages, map, left, size, sha256, frame, fits, swapped }
//
//   text      the card: (1) the frame, (2) the names with how often and the giver of each fold, (3) the appearances (the sentence, the stretch marked, one sentence either side), (4) the edges, as plain
//             sentences with polarity as fact, (5) the pronoun bindings, (6) what a giver states (supplied by the caller), (7) what the card does not hold, as fact. Every selectable item carries
//             an ORDINAL local to the card. No id, no address, no ref_ string, and none of the instrument's own part-names (the ledger, the fold, the index): "the reading of this text".
//   map       PRIVATE. Each ordinal → its fold address (ledger span ids, referent id, edge id). It is a separate return value and is never part of `text` or `messages`; a model answers by choosing an
//             ordinal, and this turns the choice back into addresses mechanically (a model that wrote an address would be fabricating one).
//   messages  [{ role: "system", content: text }, { role: "user", content: question }]: the question last and verbatim.
//   left      per section, the number of items the card has and did not show. NOTHING IS TRUNCATED SILENTLY: each omission is a count in the card ("Seven more appearances exist and are not shown")
//             and here. `window` (characters, the loaded window; never a default here) orders what is spent by the question: the frame, the names and the not-held statements are mandatory; if they alone do not fit,
//             `fits` is false and they are not shrunk.
//   swapped   with `swap: { <base name>: <invented base name> }`, every surface of the referent replaced consistently, the case forms generated by the declension table that folded them, and the old stems still
//             present counted in `leaks`. The swapped card has the same lines, ordinals and map: the control that tells the card from the model's memory of the novel.
//
// Pure; imports the page-safe hash and the pure declension folder (declension.js imports nothing) only (the reader's import graph stays free of node:). It asks no giver: the kinship rows are the caller's input.
import { sha256hex } from "./sha256hex.js";
import { createDeclensionFolder } from "./declension.js";

export const FOLDED_CARD_SCHEMA = "FoldedCard@1";
export const QUESTION_KINDS = Object.freeze(["identity", "contradiction", "gap", "derivation", "free"]);
/** what is spent first, by the kind of question (the later sections get what is left) */
const PRIORITY = Object.freeze({
  identity: ["appearances", "bindings", "edges", "stated"],
  contradiction: ["edges", "appearances", "bindings", "stated"],
  gap: ["stated", "edges", "appearances", "bindings"],
  derivation: ["stated", "edges", "appearances", "bindings"],
  free: ["appearances", "edges", "bindings", "stated"],
});
const ORDER = Object.freeze(["appearances", "edges", "bindings", "stated"]);   // the canonical order of the item sections in the card
const NOUN = Object.freeze({ appearances: ["appearance", "appearances"], edges: ["statement about it", "statements about it"], bindings: ["pronoun binding", "pronoun bindings"], stated: ["row a giver states", "rows a giver states"] });
const SKIP = (n, section) => `${n === 1 ? "One more" : `${n} more`} ${NOUN[section][n === 1 ? 0 : 1]} exist${n === 1 ? "s" : ""} in the reading and ${n === 1 ? "is" : "are"} not shown.`;

const h = (s) => sha256hex(String(s));
const fold = (s) => String(s ?? "").normalize("NFKD").replace(/\p{M}/gu, "").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();
const tokensOf = (s) => fold(s).split(" ").filter(Boolean);
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const cap = (w, like) => (like && like[0] === like[0].toUpperCase() && like[0] !== like[0].toLowerCase() ? w[0].toUpperCase() + w.slice(1) : w);

function sentenceIndexer(sentences) {
  return (pos) => { let lo = 0, hi = sentences.length - 1, best = 0; while (lo <= hi) { const m = (lo + hi) >> 1; if (sentences[m].offset <= pos) { best = m; lo = m + 1; } else hi = m - 1; } return best; };
}

/** the sentence with each stretch [a, b) (document offsets) marked in brackets */
function marked(sentence, stretches) {
  const text = sentence.text;
  const rel = stretches.map(([a, b]) => [a - sentence.offset, b - sentence.offset]).filter(([a, b]) => a >= 0 && b <= text.length && b > a).sort((x, y) => y[0] - x[0]);
  let out = text;
  for (const [a, b] of rel) out = `${out.slice(0, a)}[${out.slice(a, b)}]${out.slice(b)}`;
  return out.replace(/\s+/g, " ").trim();
}

/** how a form was joined to the name, in prose, with the giver of the fold */
function foldedBy(form, name, folder, giver) {
  if (form === name) return "the name most often written";
  const ft = tokensOf(form), nt = tokensOf(name);
  if (folder) for (const a of ft) for (const b of nt) if (a !== b && (folder(a, b) || folder(b, a))) return `a case form of the name: the declension table of the language (${giver}) reaches it`;
  if (ft.every((t) => nt.includes(t)) || nt.every((t) => ft.includes(t))) return "part of the name, or the name with more words: joined because one contains the other";
  return "joined to the name by the reading of this text, on the evidence of how the forms stand together";
}

/**
 * Render the card. `entry` is a read made with { referents: true }. `asOf`: a document character offset, { sentence: n }, or null (the whole text). `forWhom`: who is asking (a string or { who }).
 * `question`: { kind, text, about? } with kind one of QUESTION_KINDS; `window`: the loaded window in characters, or null (no limit asked). `stated`: [{ giver, text }]. `declension`: { prior } of the language,
 * to name the giver of a case fold and to generate an invented name's case forms. `swap`: { <base name>: <invented base name> }.
 */
export function renderCard(entry, referentId, { asOf = null, forWhom = "the reader of this card", question = { kind: "free", text: "" }, window = null, stated = [], declension = null, swap = null } = {}) {
  const L = entry?.referents;
  if (!L?.referents) throw new TypeError("renderCard needs a read made with referents: true");
  const R = L.referents.find((r) => r.id === referentId);
  if (!R) throw new TypeError("renderCard: no such referent in this reading");
  const kind = QUESTION_KINDS.includes(question?.kind) ? question.kind : "free";
  const spanById = new Map(L.spans.map((s) => [s.id, s]));
  const refById = new Map(L.referents.map((r) => [r.id, r]));
  const sentences = entry.sentences ?? [];
  const sentenceAt = sentenceIndexer(sentences);
  const lastSentence = asOf == null ? sentences.length - 1 : typeof asOf === "object" ? Math.min(asOf.sentence, sentences.length - 1) : sentenceAt(asOf);
  const known = (sid) => sentenceAt(spanById.get(sid).at[0]) <= lastSentence;

  const folder = declension?.prior ? createDeclensionFolder(declension.prior).sameStem : null;
  const giverName = declension?.prior?.provenance?.giver ? `UniMorph, ${declension.prior.provenance.giver}` : "the table the reading was given";

  // ── names: the surfaces, how often, the giver of each fold
  const own = R.mentions.map((sid) => spanById.get(sid)).filter((s) => s && known(s.id));
  const nameSpans = own.filter((s) => s.kind === "name"), pronounSpans = own.filter((s) => s.kind === "pronoun");
  const counts = new Map();
  for (const s of nameSpans) { const c = counts.get(s.text) ?? { n: 0, spans: [], first: s.at[0] }; c.n++; c.spans.push(s.id); counts.set(s.text, c); }
  const forms = [...counts].sort((a, b) => b[1].n - a[1].n || a[1].first - b[1].first);
  const name = forms[0]?.[0] ?? R.face;

  // ── the items of each section (each: { text, address })
  const items = { appearances: [], edges: [], bindings: [], stated: [] };
  const bySentence = new Map();
  for (const s of nameSpans) { const i = sentenceAt(s.at[0]); (bySentence.get(i) ?? bySentence.set(i, []).get(i)).push(s); }
  for (const i of [...bySentence.keys()].sort((a, b) => a - b)) {
    const ss = bySentence.get(i), around = [i - 1, i, i + 1].filter((j) => j >= 0 && j <= lastSentence && sentences[j]);
    const body = around.map((j) => (j === i ? marked(sentences[j], ss.map((x) => x.at)) : sentences[j].text.replace(/\s+/g, " ").trim())).join(" ");
    items.appearances.push({ text: body, address: { referent: R.id, spans: ss.map((x) => x.id), sentence: i } });
  }
  const aboutSpans = new Set(question?.about?.spans ?? []);
  if (kind === "identity" && aboutSpans.size) items.appearances.sort((a, b) => (b.address.spans.some((x) => aboutSpans.has(x)) ? 1 : 0) - (a.address.spans.some((x) => aboutSpans.has(x)) ? 1 : 0) || a.address.sentence - b.address.sentence);
  const faceOf = (id) => { const r = refById.get(id); if (!r) return "someone"; const c = new Map(); for (const sid of r.mentions) { const s = spanById.get(sid); if (s?.kind === "name") c.set(s.text, (c.get(s.text) ?? 0) + 1); } return [...c].sort((a, b) => b[1] - a[1])[0]?.[0] ?? r.face; };
  for (const e of L.edges ?? []) {
    if (!e.ends.some((n) => n.ref === R.id) || e.ends[0].ref === e.ends[1].ref) continue;
    const st = e.statements.filter((x) => x.sentence <= lastSentence); if (!st.length) continue;
    const subj = e.ends[0].ref === R.id ? name : faceOf(e.ends[0].ref), obj = e.ends[1].ref === R.id ? name : faceOf(e.ends[1].ref);
    // "+" is the reading's lens finding NO negation in the sentence, not a claim that the sentence asserts the link: said as that fact
    const pol = e.polarity === "+" ? "No negation was found in it." : e.polarity === "-" ? "A negation was found in it." : "The reading did not decide whether a negation applies to it.";
    const via = String(e.label ?? "").trim() ? `through the words “${String(e.label).trim()}”` : "next to each other, with no word between";
    const sent = sentences[st[0].sentence]; if (!sent) continue;
    items.edges.push({ text: `${subj} and ${obj} are linked ${via}. ${pol} In the sentence: ${sent.text.replace(/\s+/g, " ").trim()}${st.length > 1 ? ` (the same is read in ${st.length - 1} more sentence${st.length > 2 ? "s" : ""})` : ""}`, address: { referent: R.id, edge: e.id, spans: e.ends.map((n) => n.span), sentences: st.map((x) => x.sentence) } });
  }
  const pBy = new Map();
  for (const s of pronounSpans) { const i = sentenceAt(s.at[0]); (pBy.get(i) ?? pBy.set(i, []).get(i)).push(s); }
  for (const i of [...pBy.keys()].sort((a, b) => a - b)) {
    const ss = pBy.get(i);
    items.bindings.push({ text: `In this sentence ${ss.map((x) => `“${x.text}”`).join(" and ")} was read as ${name}: ${marked(sentences[i], ss.map((x) => x.at))}`, address: { referent: R.id, spans: ss.map((x) => x.id), sentence: i } });
  }
  (stated ?? []).forEach((row, i) => items.stated.push({ text: `According to ${row.giver}: ${row.text}`, address: { referent: R.id, giver: row.giver, row: i } }));
  const available = Object.fromEntries(ORDER.map((k) => [k, items[k].length]));

  // ── the statements of what is not held (facts), which also carry the omission counts
  const gapsOf = () => {
    const out = [];
    const plain = R.engine, mine = new Set([R.id]);
    for (const g of entry.gaps ?? []) {
      if (g.gap === "referent_merge_unearned" && g.plain === plain) out.push({ text: `The reading could not decide whether the mentions carrying different titles (${g.modifiers.join(", ")}) are one being or more than one; it holds them as one.`, address: { gap: g.gap, plain: g.plain } });
      else if (g.gap === "mention_ambiguous" && (g.candidates ?? []).some((c) => mine.has(c))) out.push({ text: `${g.count} bare mention${g.count === 1 ? "" : "s"} of the same name could not be placed with this being or with the other${(g.candidates.length - 1) === 1 ? "" : "s"} that carry it.`, address: { gap: g.gap, plain: g.plain } });
      else if (g.gap === "pronoun_ambiguous" && (g.candidates ?? []).some((c) => mine.has(c))) out.push({ text: `${g.count} pronoun${g.count === 1 ? "" : "s"} could be read as this being or as another that carries the name, and none was placed.`, address: { gap: g.gap, plain: g.plain } });
      else if (g.gap === "referent_split" && (g.referents ?? []).includes(R.id)) out.push({ text: `This being was separated from ${(g.referents ?? []).filter((x) => x !== R.id).map(faceOf).join(", ")} on the ground of ${g.by === "numeral" ? "a different numeral after the name" : "a different title in one sentence"}; the reading holds that as a cue, not as a certainty.`, address: { gap: g.gap, plain: g.plain } });
    }
    return out;
  };
  const gaps = gapsOf();

  // ── what fits: mandatory = frame, names, the not-held statements (with the counts); the item sections by the question's order
  const frameText = `This card is for ${typeof forWhom === "object" ? forWhom.who : forWhom}. It is about one being named in the text: ${name}. It holds what the reading of the text found about ${name} up to ${asOf == null ? "the end of the text" : `sentence ${lastSentence + 1} of ${sentences.length}`}, and nothing from outside the text. The question that follows is of the kind “${kind}”.`;
  const chosen = Object.fromEntries(ORDER.map((k) => [k, 0]));
  const build = () => {
    const lines = [], map = [];
    let ord = 0;
    const put = (text, section, address) => { ord++; lines.push(`(${ord}) ${text}`); map.push({ ordinal: ord, section, address }); };
    lines.push("1. Frame", frameText, "");
    lines.push(`2. Names of ${name}`, `${nameSpans.length} written mention${nameSpans.length === 1 ? "" : "s"} in this part of the text, in ${forms.length} form${forms.length === 1 ? "" : "s"}.`);
    for (const [f, c] of forms) put(`“${f}” — written ${c.n} time${c.n === 1 ? "" : "s"}; ${foldedBy(f, name, folder, giverName)}.`, "names", { referent: R.id, spans: c.spans, form: f });
    lines.push("");
    const sec = (title, key, empty) => {
      lines.push(title);
      if (!items[key].length) lines.push(empty);
      for (const it of items[key].slice(0, chosen[key])) put(it.text, key, it.address);
      if (available[key] - chosen[key] > 0) lines.push(SKIP(available[key] - chosen[key], key));
      lines.push("");
    };
    sec(`3. Where ${name} appears`, "appearances", "No written mention of the name is in this part of the text.");
    sec(`4. What ${name} does and what is done to ${name}\nEach line links two names through the words that stand between them in one sentence; the sentence is quoted.`, "edges", "The reading found no statement with this being at one end.");
    sec(`5. Whom ${name} is bound to by a pronoun`, "bindings", "No pronoun was read as this being.");
    sec(`6. What a giver states about ${name}`, "stated", "No giver row about this being was supplied.");
    lines.push("7. What the card does not hold");
    const facts = [];
    if (!items.stated.length) facts.push({ text: `No giver states anything about ${name} here; kinship, rank and role are not held.`, address: { gap: "no_giver_rows", referent: R.id } });
    if (!items.bindings.length) facts.push({ text: "No pronoun was read as this being, so the pronouns of the text are not held for it.", address: { gap: "no_pronoun_bound", referent: R.id } });
    for (const g of gaps) facts.push(g);
    for (const f of facts) put(f.text, "gaps", f.address);
    return { lines, map };
  };
  // spend the window in the question's order, one item at a time, in whole items; recompute until the card fits or nothing more can be taken
  const render = () => { const { lines, map } = build(); return { text: lines.join("\n").replace(/\n{3,}/g, "\n\n").trim(), map }; };
  for (const k of ORDER) chosen[k] = 0;
  let r = render(), fits = true;
  if (window != null) {
    const mandatory = r.text.length;
    if (mandatory > window) fits = false;
    else for (const k of PRIORITY[kind]) {
      while (chosen[k] < available[k]) { chosen[k]++; const t = render(); if (t.text.length > window) { chosen[k]--; break; } r = t; }
    }
    r = render();
  } else for (const k of ORDER) chosen[k] = available[k];
  if (window == null) r = render();

  let text = r.text;
  const left = Object.fromEntries(ORDER.map((k) => [k, available[k] - chosen[k]]));

  // ── the name-swap rendering
  let swapped = null;
  if (swap && Object.keys(swap).length) {
    const prior = declension?.prior, pairs = new Map(), unmapped = new Set();
    const baseOf = (tok) => { for (const [k, v] of Object.entries(swap)) if (fold(k) === fold(tok)) return [k, v, null]; if (prior) for (const [k, v] of Object.entries(swap)) for (const rule of prior.rules) if (tok.toLowerCase().endsWith(rule.from) && tok.toLowerCase().slice(0, tok.length - rule.from.length) + rule.to === k.toLowerCase()) return [k, v, rule]; return null; };
    const nameTokens = new Set(); for (const [f] of forms) for (const t of f.split(/[\s]+/)) if (t) nameTokens.add(t.replace(/^[«"“(\[]+|[»"”)\],.;:!?]+$/g, ""));
    for (const tok of nameTokens) {
      const b = baseOf(tok);
      if (!b) { if (/^\p{Lu}/u.test(tok)) unmapped.add(tok); continue; }
      const [, invented, rule] = b;
      if (!rule) pairs.set(tok, cap(invented, tok));
      else if (invented.toLowerCase().endsWith(rule.to)) pairs.set(tok, cap(invented.slice(0, invented.length - rule.to.length) + rule.from, tok));
      else { pairs.set(tok, cap(invented, tok)); unmapped.add(`${tok} (the invented name does not end as the fold's rule needs)`); }
    }
    // the old stems still present (a form the fold does not list) are counted
    const stems = [...new Set([...Object.keys(swap)].map((k) => k.slice(0, Math.max(3, k.length - 1))))];
    for (const [from, to] of [...pairs].sort((a, b) => b[0].length - a[0].length)) text = text.replace(new RegExp(`(?<![\\p{L}\\p{N}])${escapeRe(from)}(?![\\p{L}\\p{N}])`, "gu"), to);
    const leaks = stems.flatMap((s) => [...text.matchAll(new RegExp(`(?<![\\p{L}])${escapeRe(s)}[\\p{L}]*`, "giu"))].map((m) => m[0]));   // a word that BEGINS with the old stem
    swapped = { pairs: [...pairs], unmapped: [...unmapped], leaks: leaks.length, leaked: [...new Set(leaks)] };
  }

  const messages = [{ role: "system", content: text }, { role: "user", content: String(question?.text ?? "") }];
  return {
    schema: FOLDED_CARD_SCHEMA, text, question: String(question?.text ?? ""), messages, map: r.map, left, fits,
    size: { chars: text.length, lines: text.split("\n").length, approxTokens: Math.ceil(text.length / 4) },
    sha256: h(text), frame: { forWhom, asOf: asOf == null ? null : lastSentence, kind, window }, swapped,
    available,
  };
}
